def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    abs_n = abs(n)
    for x in range(1, int(abs_n ** 0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            for X, Y in [(x, y), (-x, -y)]:
                if X % 2 == Y % 2:
                    a = (X + Y) // 2
                    b = (X - Y) // 2
                    if a * a - b * b == n:
                        return True
    return False
