def find_solution(a, b, n):

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - aa // bb * y1
        return (gcd, x, y)
    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'
    x0 *= n // gcd
    y0 *= n // gcd
    b_div = b // gcd
    a_div = a // gcd
    from math import ceil, floor
    k_min = ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    k_max = floor(y0 / a_div) if a_div != 0 else float('inf')
    if k_min > k_max:
        return 'No solution'
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return 'No solution'
    return ('x = ', x, ', y = ', y)
