    s = num
    n = len(s)
    if all((ch == '9' for ch in s)):
        return '1' + '0' * (n - 1) + '1'

    def mirror_left_to_right(s_list):
        length = len(s_list)
        half = length // 2
        for i in range(half):
            s_list[-(i + 1)] = s_list[i]
        return s_list
    s_list = list(s)
    pal_list = mirror_left_to_right(s_list[:])
    pal_str = ''.join(pal_list)
    if pal_str > s:
        return pal_str
    half = n // 2
    is_odd = n % 2 == 1
    left = s_list[:half]
    if is_odd:
        middle = int(s_list[half])
    else:
        middle = None
    if is_odd:
        middle += 1
        if middle == 10:
            middle = 0
            left_num = int(''.join(map(str, left))) + 1
            left_str = str(left_num).zfill(half)
            if len(left_str) > half:
                return '1' + '0' * (n - 1) + '1'
            left = list(map(int, left_str))
        pal_list = left + [middle] + left[::-1]
    else:
        left_num = int(''.join(map(str, left))) + 1
        left_str = str(left_num).zfill(half)
        if len(left_str) > half:
            return '1' + '0' * (n - 1) + '1'
        left = list(map(int, left_str))
        pal_list = left + left[::-1]
    return ''.join(map(str, pal_list))
