T = TypeVar('T', bound=Sequence)

def remove_column(nested: T, col: int) -> T:
    outer_type = type(nested)
    if not nested:
        return outer_type()
    inner_type = type(nested[0])

    def remove_from_inner(inner):
        if col < 0 or col >= len(inner):
            return inner
        return inner_type(inner[:col] + inner[col + 1:])
    return outer_type((remove_from_inner(inner) for inner in nested))
