def permute_string(sequence: List) -> List[str]:

    def backtrack(path, counter):
        if len(path) == len(sequence):
            result.append(''.join(path))
            return
        for char in counter:
            if counter[char] > 0:
                counter[char] -= 1
                path.append(char)
                backtrack(path, counter)
                path.pop()
                counter[char] += 1
    sequence = list(map(str, sequence))
    counter = {}
    for char in sequence:
        counter[char] = counter.get(char, 0) + 1
    result = []
    backtrack([], counter)
    return result
