def add_string(collection, text):
    if isinstance(collection, str):
        return text + collection
    elif isinstance(collection, list):
        return [text + str(item) for item in collection]
    elif isinstance(collection, tuple):
        return tuple((text + str(item) for item in collection))
    elif isinstance(collection, set):
        return {text + str(item) for item in collection}
    elif isinstance(collection, dict):
        return type(collection)(((text + str(k), v) for k, v in collection.items()))
    elif isinstance(collection, Iterable):
        try:
            return type(collection)((text + str(item) for item in collection))
        except Exception:
            return [text + str(item) for item in collection]
    else:
        return text + str(collection)
