from collections.abc import Iterable

def substract_elements(data):
    if isinstance(data, Iterable) and (not isinstance(data, (str, bytes))):
        data = tuple(data)
        if not data:
            return ()
        first, *rest = data
        first_val = substract_elements(first) if isinstance(first, Iterable) and (not isinstance(first, (str, bytes))) else first
        if not rest:
            return (first_val,) if isinstance(first_val, tuple) else (first_val,)
        rest_vals = tuple((substract_elements(r) if isinstance(r, Iterable) and (not isinstance(r, (str, bytes))) else r for r in rest))

        def subtract(a, b):
            if isinstance(a, tuple) and isinstance(b, tuple):
                return tuple((subtract(x, y) for x, y in zip(a, b)))
            elif isinstance(a, tuple):
                return tuple((subtract(x, b) for x in a))
            elif isinstance(b, tuple):
                return tuple((subtract(a, y) for y in b))
            else:
                return a - b
        result = first_val
        for val in rest_vals:
            result = subtract(result, val)
        if isinstance(result, tuple):

            def ensure_tuple_of_tuples(x):
                if isinstance(x, tuple):
                    return tuple((ensure_tuple_of_tuples(i) for i in x))
                else:
                    return x
            return ensure_tuple_of_tuples(result)
        else:
            return (result,)
    else:
        return (data,)
