from functools import lru_cache

def get_noOfways(n, m):
    """
    Returns the number of ways to tile an n x m board with 2x1 dominoes placed 
    only horizontally or vertically without overlaps.

    Parameters:
    n (int): number of rows
    m (int): number of columns

    Returns:
    int: number of ways to tile the board
    """
    if n * m % 2 != 0:
        return 0
    if n > m:
        n, m = (m, n)
    full_mask = (1 << n) - 1

    @lru_cache(None)
    def dfs(col, prev_mask):
        if col == m:
            return 1 if prev_mask == 0 else 0

        def backtrack(row, cur_mask, next_mask):
            if row == n:
                return dfs(col + 1, next_mask)
            res = 0
            bit = 1 << row
            if prev_mask & bit:
                res += backtrack(row + 1, cur_mask, next_mask)
            else:
                if row + 1 < n and (not prev_mask & 1 << row + 1):
                    res += backtrack(row + 2, cur_mask, next_mask)
                res += backtrack(row + 1, cur_mask, next_mask | bit)
            return res
        return backtrack(0, 0, 0)
    return dfs(0, 0)
```

