def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left_half: str, odd_length: bool) -> str:
        if odd_length:
            return left_half + left_half[-2::-1]
        else:
            return left_half + left_half[::-1]

    def increment_middle(left_half: str, odd_length: bool) -> str:
        if odd_length:
            num = int(left_half)
            num += 1
            return str(num)
        else:
            num = int(left_half)
            num += 1
            return str(num)
    odd = length % 2 != 0
    mid = length // 2
    if odd:
        left_half = s[:mid + 1]
    else:
        left_half = s[:mid]
    pal = make_palindrome(left_half, odd)
    pal_int = int(pal)
    if pal_int > n:
        return pal_int
    incremented_left = increment_middle(left_half, odd)
    if len(incremented_left) > len(left_half):
        return int('1' + '0' * (length - 1) + '1')
    pal = make_palindrome(incremented_left, odd)
    return int(pal)
