        y = x1 - aa // bb * y1
        return (g, x, y)
    g = gcd(a, b)
    if n % g != 0:
        return None
    g, x0, y0 = extended_gcd(a, b)
    x0 *= n // g
    y0 *= n // g
    a_div = a // g
    b_div = b // g
    from math import ceil, floor
    k_min = ceil(-x0 / b_div)
    k_max = floor(y0 / a_div)
    if k_min > k_max:
        return None
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return None
    return (x, y)
```

