def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_all_nines(s):
        return all((ch == '9' for ch in s))
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')
    mid = length // 2
    left = s[:mid]
    middle = s[mid] if length % 2 else ''
    right = s[mid + 1:] if length % 2 else s[mid:]
    if length % 2:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]
    if int(palindrome) > num:
        return int(palindrome)
    if length % 2:
        left_middle_num = left + middle
        incremented = str(int(left_middle_num) + 1)
        if len(incremented) > len(left_middle_num):
            palindrome = incremented + incremented[:-1][::-1]
        else:
            palindrome = incremented + incremented[:-1][::-1]
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            palindrome = incremented + incremented[:-1][::-1]
        else:
            palindrome = incremented + incremented[::-1]
    return int(palindrome)
