def get_total_number_of_sequences(n: int, m: int) -> int:
    dp_prev = [1] * (m + 1)
    for i in range(2, n + 1):
        prefix = [0] * (m + 1)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp_prev[x]
        dp_curr = [0] * (m + 1)
        for x in range(1, m + 1):
            max_y = x // 2
            if max_y >= 1:
                dp_curr[x] = prefix[max_y]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:]) if n >= 1 else 0
