def text_match_two_three(text):
    """
    Return True if the string contains a substring where a char repeats twice followed immediately by another char repeating three times.
    For example, 'aabb' does NOT match since it's 2 of one char then 2 of another.
    But 'aabbb' matches since 'aa' then 'bbb'.
    """
    n = len(text)
    for i in range(n - 4):
        if text[i] == text[i + 1]:
            if text[i + 2] == text[i + 3] == text[i + 4]:
                if text[i] != text[i + 2]:
                    return True
    return False
