from typing import Tuple, Union

def substract_elements(t: Tuple) -> Union[int, float]:

    def flatten_and_subtract(elements):
        it = iter(elements)
        try:
            result = next(it)
        except StopIteration:
            return 0
        for e in it:
            if isinstance(e, tuple):
                result -= flatten_and_subtract(e)
            else:
                result -= e
        return result

    def recursive_subtract(tpl):
        it = iter(tpl)
        try:
            acc = next(it)
        except StopIteration:
            return 0
        if isinstance(acc, tuple):
            acc = recursive_subtract(acc)
        for elem in it:
            if isinstance(elem, tuple):
                acc -= recursive_subtract(elem)
            else:
                acc -= elem
        return acc
    return recursive_subtract(t)
```

