def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    drops = 0
    drop_index = -1
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1
            drop_index = i
            if drops > 1:
                return False
    if drops == 0:
        return True
    k = n - (drop_index + 1)
    rotated = arr[-k:] + arr[:-k]
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True
