def monotonic(l: Union[list, str]) -> Union[bool, Tuple[bool, Union[int, str]]]:

    def all_unique(lst):
        if not lst:
            return True
        head, *tail = lst
        if head in tail:
            return False
        return all_unique(tail)

    def is_monotonic_increasing(lst):
        if len(lst) < 2:
            return True
        return lst[0] < lst[1] and is_monotonic_increasing(lst[1:])

    def is_monotonic_decreasing(lst):
        if len(lst) < 2:
            return True
        return lst[0] > lst[1] and is_monotonic_decreasing(lst[1:])

    def sum_list(lst):
        if not lst:
            return 0
        return lst[0] + sum_list(lst[1:])

    def all_unique_str(s):
        if not s:
            return True
        head, tail = (s[0], s[1:])
        if head in tail:
            return False
        return all_unique_str(tail)

    def is_monotonic_increasing_str(s):
        if len(s) < 2:
            return True
        return s[0] < s[1] and is_monotonic_increasing_str(s[1:])

    def is_monotonic_decreasing_str(s):
        if len(s) < 2:
            return True
        return s[0] > s[1] and is_monotonic_decreasing_str(s[1:])
    if isinstance(l, list):
        if not all_unique(l):
            return False
        if is_monotonic_increasing(l) or is_monotonic_decreasing(l):
