def triples_sum_to_zero(l: list) -> bool:
    """
    Returns True if there exist three distinct elements in the list l
    that sum to zero and are all odd numbers.
    Otherwise, returns False.
    """
    odds = [x for x in l if x % 2 != 0]
    n = len(odds)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if odds[i] + odds[j] + odds[k] == 0:
                    return True
    return False
