import re

def anti_shuffle(s):
    parts = re.split('(\\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            result.append(part)
        else:
            m = re.match('([a-zA-Z]+)([^a-zA-Z]*)$', part)
            if m:
                word, trail = m.groups()
                sorted_word = ''.join(sorted(word, reverse=True))
                result.append(sorted_word + trail)
            else:
                result.append(part)
    return ''.join(result)
```

