def will_it_fly(q, w):
    n = len(q)
    if n == 1:
        balanced = False
    else:
        half = n // 2
        if n % 2 == 0:
            left_sum = sum(q[:half])
            right_sum = sum(q[half:])
        else:
            left_sum = sum(q[:half])
            right_sum = sum(q[half + 1:])
        balanced = left_sum == right_sum
    total_weight = sum(q)
    if balanced and total_weight > w:
        return True
    if not balanced and total_weight < w:
        return True
    return False
```

